// Admin → Settings → App Page Settings: the look of every page, sheet and
// modal (sizes, curves, colours, text), edited by the admin and applied live
// on every open app. Kept in `app_settings` as one row per surface
// (`page_style:<surface id>`); a value not set falls back to the app-wide
// one (surface `app`), then to the look the app ships with.
//
// Surfaces come from `page_inventory.g.dart` (every page, sheet and modal in
// the code, regenerated by `dart run scripts/page_inventory.dart`).
import 'package:flutter/material.dart';

import 'page_surfaces.dart';

export 'page_surfaces.dart';

enum StyleKind { number, color, toggle, choice }

/// One editable value of a surface.
class StyleToken {
  const StyleToken(
    this.key,
    this.label,
    this.kind, {
    this.group = 'General',
    this.fallback = 0,
    this.min = 0,
    this.max = 100,
    this.step = 1,
    this.unit = 'px',
    this.light,
    this.dark,
    this.options = const [],
  });

  final String key;
  final String label;
  final StyleKind kind;

  /// Where the editor lists it ("Text", "Layout", "Colours", or an element).
  final String group;

  /// A number's (or a toggle's, 1 for on) value when nobody set it.
  final double fallback;
  final double min, max, step;
  final String unit;

  /// A colour's value when nobody set it; null for the theme's.
  final int? light, dark;

  /// A choice's options, in order; stored as the chosen one's index.
  final List<String> options;

  const StyleToken.number(
    String key,
    String label,
    double fallback, {
    double min = 0,
    double max = 100,
    double step = 1,
    String unit = 'px',
    String group = 'Layout',
  }) : this(key, label, StyleKind.number, group: group, fallback: fallback, min: min, max: max, step: step, unit: unit);

  const StyleToken.color(String key, String label, {int? light, int? dark, String group = 'Colours'})
    : this(key, label, StyleKind.color, group: group, light: light, dark: dark);

  const StyleToken.toggle(String key, String label, {bool on = true, String group = 'Layout'})
    : this(key, label, StyleKind.toggle, group: group, fallback: on ? 1 : 0, min: 0, max: 1, unit: '');

  /// One of [options] (at least two); [fallback] is the default's index.
  const StyleToken.choice(String key, String label, List<String> options, {int fallback = 0, String group = 'Layout'})
    : this(
        key,
        label,
        StyleKind.choice,
        group: group,
        fallback: fallback * 1.0,
        min: 0,
        // An index; readers clamp it to the options there are.
        max: 9,
        unit: '',
        options: options,
      );
}

/// Surface id of the app-wide values every page, sheet and modal inherits.
