/// What every modal (dialog) can change.
const modalTokens = <StyleToken>[
  StyleToken.number('textScale', 'Text size', 1, min: 0.8, max: 1.6, step: 0.05, unit: '×', group: _text),
  StyleToken.number('titleSize', 'Title size', 24, min: 14, max: 36, group: _text),
  StyleToken.number('iconSize', 'Icon size', 24, min: 14, max: 40, group: _layout),
  StyleToken.number('cornerRadius', 'Corner curve', 28, min: 0, max: 48, group: _layout),
  StyleToken.number('buttonRadius', 'Button curve', 20, min: 0, max: 36, group: _layout),
  StyleToken.number('dim', 'Dim behind', 54, min: 0, max: 90, unit: '%', group: _layout),
  StyleToken.color('background', 'Modal background'),
];

/// The tokens of a surface kind.
List<StyleToken> tokensFor(SurfaceKind k) => switch (k) {
  SurfaceKind.page => pageTokens,
  SurfaceKind.sheet => sheetTokens,
  SurfaceKind.modal => modalTokens,
};

/// The key a [k] token is kept under on the app-wide surface: page tokens as
/// they are, sheet and modal ones prefixed (`sheet.topRadius`).
String appKey(SurfaceKind k, String key) => switch (k) {
  SurfaceKind.page => key,
  SurfaceKind.sheet => 'sheet.$key',
  SurfaceKind.modal => 'modal.$key',
};

