const _trail = 'Movement trail';
const _chosen = 'Confirm ride: chosen vehicle';

/// God View → Movement: how the line is drawn, and whether it follows the
/// roads between the reported points or goes straight from one to the next.
const trailLineStyles = ['Solid', 'Dashed', 'Dotted'];
const trailPaths = ['Straight lines', 'Follow roads'];

/// Every token [s] can change: its kind's, then its own items'.
List<StyleToken> tokensOf(SurfaceEntry s) => [...tokensFor(s.kind), ...?elementTokens[s.id]];

/// The app-wide surface's tokens: every kind's, under [appKey].
List<(SurfaceKind, StyleToken)> get appTokens => [
  for (final k in SurfaceKind.values)
    for (final t in tokensFor(k)) (k, t),
];

/// `app_settings` key of a surface's row.
String pageStyleKey(String surface) => 'page_style:$surface';

/// The surface id in a `page_style:` key; null for another key.
String? surfaceOfKey(String key) => key.startsWith('page_style:') ? key.substring('page_style:'.length) : null;

/// A colour kept as `#AARRGGBB` (or `#RRGGBB`); null when unreadable.
Color? styleColor(Object? v) {
  if (v is! String) return null;
  var hex = v.trim().replaceFirst('#', '');
  if (hex.length == 6) hex = 'FF$hex';
  if (hex.length != 8) return null;
  final n = int.tryParse(hex, radix: 16);
  return n == null ? null : Color(n);
}

/// [c] as kept: `#AARRGGBB`.
String styleHex(Color c) => '#${c.toARGB32().toRadixString(16).padLeft(8, '0').toUpperCase()}';

/// The key a colour's dark-mode value is kept under.
String darkKey(String key) => '$key.dark';

/// The admin's values, by surface id then token key. Pure.
class PageStyles {
  const PageStyles([this.values = const {}]);

  final Map<String, Map<String, Object?>> values;

  static const none = PageStyles();

  /// From `app_settings` rows (`key`, `value`); other keys are skipped.
  factory PageStyles.fromRows(Iterable<Map<String, dynamic>> rows) => PageStyles({
    for (final r in rows)
      if (surfaceOfKey('${r['key']}') case final id? when r['value'] is Map)
        id: Map<String, Object?>.from(r['value'] as Map),
  });

  Map<String, Object?>? _own(String surface) => values[surface];

  Object? _raw(String surface, SurfaceKind kind, String key) =>
      _own(surface)?[key] ?? (surface == appSurface ? null : _own(appSurface)?[appKey(kind, key)]);

  /// [t] on [surface] (of [kind]): its own value, else the app-wide one,
  /// else [StyleToken.fallback]; kept within the token's range.
  double number(String surface, SurfaceKind kind, StyleToken t) {
    final v = _raw(surface, kind, t.key);
    final n = v is num ? v.toDouble() : double.tryParse('${v ?? ''}');
    return (n ?? t.fallback).clamp(t.min, t.max).toDouble();
  }

  bool toggle(String surface, SurfaceKind kind, StyleToken t) => number(surface, kind, t) >= 0.5;

  /// [t]'s colour for [b]; null where nobody set one and it has no default
  /// (the theme's colour stays).
  Color? color(String surface, SurfaceKind kind, StyleToken t, Brightness b) {
    final dark = b == Brightness.dark;
    final set = styleColor(_raw(surface, kind, dark ? darkKey(t.key) : t.key));
    if (set != null) return set;
    final d = dark ? t.dark : t.light;
    return d == null ? null : Color(d);
  }

  /// Whether [key] (or, for a colour, its dark value) is set on [surface] or
  /// app-wide.
  bool isSet(String surface, SurfaceKind kind, String key) =>
      _raw(surface, kind, key) != null || _raw(surface, kind, darkKey(key)) != null;

  /// Whether any value is set on [surface].
  bool has(String surface) => _own(surface)?.isNotEmpty ?? false;

  /// A copy with [surface]'s values replaced by [v] (removed when empty).
  PageStyles withSurface(String surface, Map<String, Object?> v) =>
      PageStyles({...values, surface: v}..removeWhere((_, m) => m.isEmpty));
}

/// The token named [key] among [tokens].
StyleToken tokenNamed(List<StyleToken> tokens, String key) => tokens.firstWhere((t) => t.key == key);
